spec fn count_ok(a: &[i64], r: usize) -> bool { r <= a.len() }

#[effects(pure)]
#[uses(ledger::in_closed, count_ok)]
fn deposit_all(a: &mut [i64], x: i64) -> (r: usize)
    requires ledger::in_closed(x),
    ensures count_ok(a, r),
{
    let mut c: usize = 0;
    let mut k: usize = 0;
    while k < a.len()
        invariant k <= a.len(), c <= k,
        decreases a.len() - k,
    {
        a[k] = a[k].wrapping_add(x);
        c = c + 1;
        k = k + 1;
    }
    c
}
